	@Test
	void cancellationStopsCandidateFilteringAndClosesOnTheEvaluationThread() {
		SimpleValueFactory vf = SimpleValueFactory.getInstance();
		AtomicInteger incompatibleComparisons = new AtomicInteger();
		AtomicBoolean cancellationRequested = new AtomicBoolean();
		AtomicReference<MaterializedReplayJoinIterator> iteratorReference = new AtomicReference<>();
		IRI cancellationValue = new CancellingIri("urn:match", () -> {
			incompatibleComparisons.incrementAndGet();
			if (cancellationRequested.compareAndSet(false, true)) {
				iteratorReference.get().requestCancellation();
			}
		});
		MapBindingSet leftRow = new MapBindingSet(3);
		leftRow.addBinding("s", vf.createIRI("urn:shared-subject"));
		leftRow.addBinding("r", cancellationValue);
		leftRow.addBinding("t", vf.createIRI("urn:shared-third"));

		List<BindingSet> rightRows = new ArrayList<>();
		for (int i = 0; i < 128; i++) {
			MapBindingSet row = new MapBindingSet(3);
			row.addBinding("s", vf.createIRI("urn:shared-subject"));
			row.addBinding("r", vf.createIRI("urn:other-r:" + i));
			row.addBinding("t", vf.createIRI("urn:shared-third"));
			rightRows.add(row);
		}
		for (int i = 0; i < 128; i++) {
			MapBindingSet row = new MapBindingSet(3);
			row.addBinding("s", vf.createIRI("urn:other-s:" + i));
			row.addBinding("r", vf.createIRI("urn:match"));
			row.addBinding("t", vf.createIRI("urn:shared-third"));
			rightRows.add(row);
		}

		AtomicInteger leftCloseCount = new AtomicInteger();
		AtomicReference<Thread> leftCloseThread = new AtomicReference<>();
		TrackingSingleRowIteration leftIteration = new TrackingSingleRowIteration(leftRow, leftCloseCount,
				leftCloseThread);
		MaterializedReplayJoinIterator iterator = new MaterializedReplayJoinIterator(ignored -> leftIteration,
				ignored -> new CloseableIteratorIteration<>(rightRows.iterator()), null, EmptyBindingSet.getInstance(),
				false,
				List.of("s", "r", "t"), DefaultCollectionFactory::new);
		iteratorReference.set(iterator);

		assertThat(iterator.hasNext()).isFalse();
		assertThat(incompatibleComparisons)
				.as("cancellation should stop filtering after the first incompatible candidate")
				.hasValue(1);
		assertThat(leftCloseCount).hasValue(1);
		assertThat(leftCloseThread.get()).isSameAs(Thread.currentThread());
	}

	@Test
	void rightFailureRemainsPrimaryWhenEveryOwnedResourceAlsoFailsToClose() {
		IllegalStateException rightFailure = new IllegalStateException("right iteration failed");
		IllegalStateException rightCloseFailure = new IllegalStateException("right iteration close failed");
		IllegalStateException indexCloseFailure = new IllegalStateException("index close failed");
		IllegalStateException factoryCloseFailure = new IllegalStateException("factory close failed");
		AtomicInteger rightCloseCount = new AtomicInteger();
		AtomicInteger leftEvaluationCount = new AtomicInteger();
		ThrowingCollectionFactory factory = new ThrowingCollectionFactory(indexCloseFailure, factoryCloseFailure);
		MaterializedReplayJoinIterator iterator = new MaterializedReplayJoinIterator(
				ignored -> {
					leftEvaluationCount.incrementAndGet();
					return new CloseableIteratorIteration<>(List.<BindingSet>of().iterator());
				},
				ignored -> new ThrowingRightIteration(rightFailure, rightCloseFailure, rightCloseCount), null,
				EmptyBindingSet.getInstance(), false, List.of(), () -> factory);

		Throwable observedFailure = catchThrowable(iterator::hasNext);

		assertThat(observedFailure).isSameAs(rightFailure);
		assertThat(rightFailure.getSuppressed()).contains(rightCloseFailure, indexCloseFailure);
		assertThat(indexCloseFailure.getSuppressed()).contains(factoryCloseFailure);
		assertThat(rightCloseCount).hasValue(1);
		assertThat(factory.indexCloseCount).hasValue(1);
		assertThat(factory.closeCount).hasValue(1);
		assertThat(leftEvaluationCount).hasValue(0);
	}

