	@Test
	void partialOptionalBindingsReplayOnlyCompatibleRowsAndPreserveDuplicates() {
		SimpleValueFactory vf = SimpleValueFactory.getInstance();
		AtomicInteger equalityChecks = new AtomicInteger();
		List<Statement> statements = new ArrayList<>();
		for (int i = 0; i < LEFT_ROWS; i++) {
			CountingIri subject = new CountingIri("urn:left:" + i, equalityChecks);
			CountingIri object = new CountingIri("urn:value:" + i, equalityChecks);
			statements.add(vf.createStatement(subject, vf.createIRI("urn:rare"), object));
		}

		CountingVolatileFunction function = new CountingVolatileFunction();
		FunctionRegistry registry = FunctionRegistry.getInstance();
		registry.add(function);
		try {
			StringBuilder queryText = new StringBuilder(
					"SELECT ?s ?r ?free ?nonce WHERE { ?s <urn:rare> ?r . OPTIONAL { VALUES (?s ?r ?free) { ");
			for (int i = 0; i < DECOY_ROWS; i++) {
				queryText.append("(<urn:decoy:")
						.append(i)
						.append("> <urn:value:")
						.append(i % LEFT_ROWS)
						.append("> ")
						.append(i)
						.append(") ");
			}
			for (int i = 0; i < DUPLICATE_WILDCARD_ROWS; i++) {
				queryText.append("(UNDEF UNDEF 777) ");
			}
			queryText.append("(UNDEF <urn:value:0> 778) (<urn:left:0> UNDEF 779) ")
					.append("(<urn:left:0> <urn:value:0> 780) ");
			queryText.append("} BIND(<").append(VOLATILE_FUNCTION_URI).append(">() AS ?nonce) } }");

			ParsedTupleQuery parsed = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, queryText.toString(), null);
			List<LeftJoin> joins = new ArrayList<>();
			parsed.getTupleExpr().visit(new AbstractSimpleQueryModelVisitor<RuntimeException>() {
				@Override
				public void meet(LeftJoin node) {
					if (node.getLeftArg().getBindingNames().contains("s")
							&& node.getRightArg().getBindingNames().contains("s")
							&& containsVolatileFunction(node.getRightArg())) {
						joins.add(node);
					}
					super.meet(node);
				}
			});
			assertThat(joins).hasSize(1);
			LeftJoin replayCandidate = joins.get(0);
			assertThat(replayCandidate.getLeftArg().getAssuredBindingNames()).contains("s");
			assertThat(replayCandidate.getRightArg().getAssuredBindingNames()).doesNotContain("s");
			assertThat(QueryEvaluationUtility.isRepeatable(replayCandidate.getRightArg())).isFalse();

			DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new ListTripleSource(statements, vf),
					null);
			List<BindingSet> results = new ArrayList<>();
			try (CloseableIteration<BindingSet> iteration = strategy.precompile(parsed.getTupleExpr())
					.evaluate(EmptyBindingSet.getInstance())) {
				while (iteration.hasNext()) {
					results.add(iteration.next());
				}
			}
			int observedEqualityChecks = equalityChecks.get();
			int observedFunctionEvaluations = function.evaluations.get();

			assertThat(replayCandidate.getAlgorithmName())
					.as("right subtree: %s", replayCandidate.getRightArg())
					.isEqualTo(MaterializedReplayJoinIterator.class.getSimpleName());
			assertThat(results).hasSize(LEFT_ROWS * DUPLICATE_WILDCARD_ROWS + 3);
			Map<Value, Integer> rowsPerLeftSubject = new HashMap<>();
			Map<Value, Integer> rowsPerFreeValue = new HashMap<>();
			for (BindingSet result : results) {
				rowsPerFreeValue.merge(result.getValue("free"), 1, Integer::sum);
				assertThat(result.getValue("nonce")).isEqualTo(vf.createLiteral("ok"));
				rowsPerLeftSubject.merge(result.getValue("s"), 1, Integer::sum);
			}
			assertThat(rowsPerLeftSubject).hasSize(LEFT_ROWS);
			for (Map.Entry<Value, Integer> entry : rowsPerLeftSubject.entrySet()) {
				int expected = entry.getKey().equals(vf.createIRI("urn:left:0"))
						? DUPLICATE_WILDCARD_ROWS + 3
						: DUPLICATE_WILDCARD_ROWS;
				assertThat(entry.getValue())
						.as("duplicate and partially unbound rows remain distinct solutions for %s", entry.getKey())
						.isEqualTo(expected);
			}
			assertThat(rowsPerFreeValue).containsEntry(vf.createLiteral("777", CoreDatatype.XSD.INTEGER),
					LEFT_ROWS * DUPLICATE_WILDCARD_ROWS)
					.containsEntry(vf.createLiteral("778", CoreDatatype.XSD.INTEGER), 1)
					.containsEntry(vf.createLiteral("779", CoreDatatype.XSD.INTEGER), 1)
					.containsEntry(vf.createLiteral("780", CoreDatatype.XSD.INTEGER), 1);
			assertThat(observedFunctionEvaluations).isEqualTo(DECOY_ROWS + DUPLICATE_WILDCARD_ROWS + 3);

			assertThat(observedEqualityChecks)
					.as("incompatible bound keys must not be compared once for every left/right pair")
					.isLessThan(LEFT_ROWS * DECOY_ROWS / 4);
		} finally {
			registry.remove(function);
		}
	}

	private static boolean containsVolatileFunction(QueryModelNode node) {
		AtomicInteger calls = new AtomicInteger();
		node.visit(new AbstractSimpleQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(FunctionCall call) {
				if (VOLATILE_FUNCTION_URI.equals(call.getURI())) {
					calls.incrementAndGet();
				}
				super.meet(call);
			}
		});
		return calls.get() > 0;
	}

	private static final class CountingVolatileFunction implements Function {
		private final AtomicInteger evaluations = new AtomicInteger();

		@Override
		public String getURI() {
			return VOLATILE_FUNCTION_URI;
		}

		@Override
		public Value evaluate(ValueFactory valueFactory, Value... args) {
			evaluations.incrementAndGet();
			return valueFactory.createLiteral("ok");
		}
	}

	private static final class ListTripleSource implements TripleSource {
		private final List<Statement> statements;
		private final ValueFactory valueFactory;

		private ListTripleSource(List<Statement> statements, ValueFactory valueFactory) {
			this.statements = statements;
			this.valueFactory = valueFactory;
		}

		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate, Value object,
				Resource... contexts) {
			return new CloseableIteratorIteration<>(statements.stream()
					.filter(statement -> subject == null || subject.equals(statement.getSubject()))
					.filter(statement -> predicate == null || predicate.equals(statement.getPredicate()))
					.filter(statement -> object == null || object.equals(statement.getObject()))
					.filter(statement -> contexts.length == 0 || Arrays.stream(contexts)
							.anyMatch(context -> Objects.equals(context, statement.getContext())))
					.iterator());
		}

		@Override
		public ValueFactory getValueFactory() {
			return valueFactory;
		}
	}

	private static final class CountingIri implements IRI {
		private final String iri;
		private final AtomicInteger equalityChecks;

		private CountingIri(String iri, AtomicInteger equalityChecks) {
			this.iri = iri;
			this.equalityChecks = equalityChecks;
		}

		@Override
		public String stringValue() {
			return iri;
		}

		@Override
		public String getNamespace() {
			return iri.substring(0, iri.lastIndexOf(':') + 1);
		}

		@Override
		public String getLocalName() {
			return iri.substring(iri.lastIndexOf(':') + 1);
		}

		@Override
		public int hashCode() {
			return iri.hashCode();
		}

		@Override
		public boolean equals(Object other) {
			equalityChecks.incrementAndGet();
			return other instanceof IRI && iri.equals(((IRI) other).stringValue());
		}
	}

	private static final class CountingMapCollectionFactory extends DefaultCollectionFactory {
		private final AtomicInteger lookups;

		private CountingMapCollectionFactory(AtomicInteger lookups) {
			this.lookups = lookups;
		}

		@Override
		public <K, V> Map<K, V> createMap() {
			return new HashMap<>() {
				@Override
				public V get(Object key) {
					lookups.incrementAndGet();
					return super.get(key);
				}
			};
		}
	}

