	private static final class CancellingIri implements IRI {
		private final String iri;
		private final Runnable onMismatch;

		private CancellingIri(String iri, Runnable onMismatch) {
			this.iri = iri;
			this.onMismatch = onMismatch;
		}

		@Override
		public String stringValue() {
			return iri;
		}

		@Override
		public String getNamespace() {
			return iri.substring(0, iri.lastIndexOf(':') + 1);
		}

		@Override
		public String getLocalName() {
			return iri.substring(iri.lastIndexOf(':') + 1);
		}

		@Override
		public int hashCode() {
			return iri.hashCode();
		}

		@Override
		public boolean equals(Object other) {
			boolean equal = other instanceof IRI && iri.equals(((IRI) other).stringValue());
			if (!equal) {
				onMismatch.run();
			}
			return equal;
		}
	}

	private static final class TrackingSingleRowIteration extends LookAheadIteration<BindingSet> {
		private final BindingSet row;
		private final AtomicInteger closeCount;
		private final AtomicReference<Thread> closeThread;
		private boolean emitted;

		private TrackingSingleRowIteration(BindingSet row, AtomicInteger closeCount,
				AtomicReference<Thread> closeThread) {
			this.row = row;
			this.closeCount = closeCount;
			this.closeThread = closeThread;
		}

		@Override
		protected BindingSet getNextElement() {
			if (emitted) {
				return null;
			}
			emitted = true;
			return row;
		}

		@Override
		protected void handleClose() {
			closeCount.incrementAndGet();
			closeThread.set(Thread.currentThread());
		}
	}

	private static final class ThrowingRightIteration implements CloseableIteration<BindingSet> {
		private final RuntimeException rightFailure;
		private final RuntimeException closeFailure;
		private final AtomicInteger closeCount;

		private ThrowingRightIteration(RuntimeException rightFailure, RuntimeException closeFailure,
				AtomicInteger closeCount) {
			this.rightFailure = rightFailure;
			this.closeFailure = closeFailure;
			this.closeCount = closeCount;
		}

		@Override
		public boolean hasNext() {
			throw rightFailure;
		}

		@Override
		public BindingSet next() {
			throw new UnsupportedOperationException();
		}

		@Override
		public void close() {
			closeCount.incrementAndGet();
			throw closeFailure;
		}
	}

	private static final class ThrowingCollectionFactory extends DefaultCollectionFactory {
		private final RuntimeException indexCloseFailure;
		private final RuntimeException factoryCloseFailure;
		private final AtomicInteger indexCloseCount = new AtomicInteger();
		private final AtomicInteger closeCount = new AtomicInteger();

		private ThrowingCollectionFactory(RuntimeException indexCloseFailure, RuntimeException factoryCloseFailure) {
			this.indexCloseFailure = indexCloseFailure;
			this.factoryCloseFailure = factoryCloseFailure;
		}

		@Override
		public BindingSetCompatibilityIndex createBindingSetCompatibilityIndex(List<String> sharedBindingNames) {
			return new BindingSetCompatibilityIndex() {
				@Override
				public void add(BindingSet bindingSet) {
				}

				@Override
				public Iterator<BindingSet> candidateRows(BindingSet bindings) {
					return List.<BindingSet>of().iterator();
				}

				@Override
				public void close() {
					indexCloseCount.incrementAndGet();
					throw indexCloseFailure;
				}
			};
		}

		@Override
		public void close() {
			closeCount.incrementAndGet();
			throw factoryCloseFailure;
		}
	}
